#' E-value for Unmeasured Confounding
#'
#' Computes the E-value, the minimum strength of association that an 
#' unmeasured confounder would need to have with both the exposure and the 
#' outcome - above and beyond the measured covariates - to fully explain away 
#' an observed exposure-outcome association (VanderWeele & Ding, 2017). An 
#' E-value is reported for the point estimate and for the confidence-interval 
#' limit closest to the null. Larger E-values indicate results more robust to 
#' unmeasured confounding. Accepts risk ratios, odds ratios, hazard ratios, or 
#' standardized mean differences.
#' 
#'
#' @examples
#' \donttest{
#' evalue(
#'     effectType = "RR",
#'     estimate = 3.9,
#'     ci_lower = 1.8,
#'     ci_upper = 8.7,
#'     rare = FALSE)
#'}
#' @param data Optional data frame. The E-value is computed from the estimate
#'   and confidence limits entered below; a data frame is not required.
#' @param effectType The type of effect estimate. Odds and hazard ratios are
#'   converted to an approximate risk-ratio scale before the E-value is
#'   computed.
#' @param estimate The observed effect estimate (ratio measures on their
#'   natural scale, > 0; a standardized mean difference on the d scale).
#' @param ci_lower Lower confidence limit of the estimate. Set both limits to
#'   0 to compute the E-value for the point estimate only.
#' @param ci_upper Upper confidence limit of the estimate.
#' @param rare Whether the outcome is rare (affects the odds-ratio /
#'   hazard-ratio to risk-ratio conversion). When rare, OR and HR approximate
#'   the RR directly.
#' @param trueValue The value of the effect measure representing no effect (1
#'   for ratio measures). The E-value is computed for the association relative
#'   to this value.
#' @param showPlot Display the bounding curve of confounder associations that
#'   would explain away the estimate, with the E-value marked.
#' @param showSummary Display a plain-language interpretation of the E-value.
#' @param showExplanation Display an explanation of the E-value methodology.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mainTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$mainTable$asDF}
#'
#' \code{as.data.frame(results$mainTable)}
#'
#' @export
evalue <- function(
    data,
    effectType = "RR",
    estimate = 2,
    ci_lower = 0,
    ci_upper = 0,
    rare = FALSE,
    trueValue = 1,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("evalue requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- evalueOptions$new(
        effectType = effectType,
        estimate = estimate,
        ci_lower = ci_lower,
        ci_upper = ci_upper,
        rare = rare,
        trueValue = trueValue,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- evalueClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

